import type { MetadataRoute } from "next";

// Required for `output: 'export'` — the manifest must be prerendered.
export const dynamic = "force-static";

/**
 * Web app manifest — generated by the manifest file convention and served at
 * /manifest.webmanifest. Uses the TatoIQ brand colors so an installed app
 * picks up navy chrome.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "TatoIQ — Tax preparation portal",
    short_name: "TatoIQ",
    description:
      "Guided tax preparation with human preparer review and Saggio, the cited tax-education assistant.",
    start_url: "/dashboard",
    display: "standalone",
    background_color: "#ffffff",
    theme_color: "#102138",
    icons: [
      { src: "/icon", sizes: "64x64", type: "image/png" },
      { src: "/apple-icon", sizes: "180x180", type: "image/png" },
    ],
  };
}
